/**
 * Minimal HTTP router for Node.js.
 */
class Router {
  constructor() {
    this._routes = [];
  }

  get(path, handler) {
    this._routes.push({ method: 'GET', path, handler });
  }

  post(path, handler) {
    this._routes.push({ method: 'POST', path, handler });
  }

  /**
   * Match a request against registered routes.
   * Returns { handler, params } or null if no match.
   */
  match(method, url) {
    for (const route of this._routes) {
      // BUG 1: compares method case-sensitively but input may be lowercase
      if (route.method !== method) continue;

      const routeParts = route.path.split('/');
      const urlParts = url.split('/');
      if (routeParts.length !== urlParts.length) continue;

      const params = {};
      let matched = true;
      for (let i = 0; i < routeParts.length; i++) {
        if (routeParts[i].startsWith(':')) {
          // BUG 2: stores the pattern name with the colon, not without
          params[routeParts[i]] = urlParts[i];
        } else if (routeParts[i] !== urlParts[i]) {
          matched = false;
          break;
        }
      }
      if (matched) return { handler: route.handler, params };
    }
    return null;
  }

  /**
   * Dispatch a request. Calls errorHandler(err, req, res) on synchronous throw.
   */
  dispatch(method, url, req, res, errorHandler) {
    const result = this.match(method, url);
    if (!result) {
      res.statusCode = 404;
      res.end('Not Found');
      return;
    }
    req.params = result.params;
    // BUG 3: does not wrap handler in try/catch — errors propagate uncaught
    result.handler(req, res);
  }
}

module.exports = Router;

