const assert = require('assert');
const Router = require('./router');

const router = new Router();
router.get('/users/:id', (req, res) => { res.end('user:' + req.params.id); });
router.post('/items', (req, res) => { res.end('created'); });

// test case-insensitive method matching
let matched = router.match('get', '/users/42');
assert.ok(matched, 'should match lowercase get');
assert.strictEqual(matched.params.id, '42', 'param id should be 42 without colon');

// test POST
let postMatch = router.match('POST', '/items');
assert.ok(postMatch, 'should match POST /items');

// test no match
assert.strictEqual(router.match('GET', '/other'), null);

// test dispatch with error handler
const errRouter = new Router();
errRouter.get('/boom', () => { throw new Error('oops'); });
let caught = null;
const fakeReq = {};
const fakeRes = { end: () => {} };
errRouter.dispatch('get', '/boom', fakeReq, fakeRes, (err) => { caught = err; });
assert.ok(caught instanceof Error, 'error handler should be called on throw');
assert.strictEqual(caught.message, 'oops');

console.log('All tests passed!');
